#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SCREEN = ROOT / 'apps/mobile/lib/features/nearby/nearby_local_screen.dart'
text = SCREEN.read_text()

old = '''      body: SafeArea(\n        child: Column(\n          children: <Widget>[\n            if (_busy) const LinearProgressIndicator(minHeight: 2),\n            Padding(\n              padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),\n              child: _PrivateLocationCard(\n                locationAccess: _locationAccess,\n                location: _location,\n                onUseLocation: _useMyLocationPrivately,\n              ),\n            ),\n            if (!_contactAccess.canReadContacts)\n              Padding(\n                padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),\n                child: _ContactPermissionCard(\n                  access: _contactAccess,\n                  onEnable: _enableContacts,\n                ),\n              ),\n            if (_message != null)\n              Padding(\n                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),\n                child: MaterialBanner(\n                  content: Text(_message!),\n                  actions: <Widget>[\n                    TextButton(\n                      onPressed: () => setState(() => _message = null),\n                      child: const Text('Dismiss'),\n                    ),\n                  ],\n                ),\n              ),\n            Padding(\n              padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),\n              child: SearchBar(\n                hintText: 'Search contacts',\n                leading: const Icon(Icons.search),\n                onChanged: (String value) => setState(() => _query = value),\n              ),\n            ),\n            _NearbyControls(\n              distanceFilter: _distanceFilter,\n              sortOrder: _sortOrder,\n              onDistanceFilterChanged: (NearbyDistanceFilter value) {\n                setState(() => _distanceFilter = value);\n              },\n              onSortChanged: (NearbySortOrder value) {\n                setState(() => _sortOrder = value);\n              },\n            ),\n            Expanded(\n              child: rows.isEmpty\n                  ? _EmptyNearbyResults(\n                      access: _contactAccess,\n                      hasContacts: _contacts.isNotEmpty,\n                      hasLocation: _location != null,\n                      hasActiveFilter:\n                          _distanceFilter != NearbyDistanceFilter.all ||\n                              _query.trim().isNotEmpty,\n                    )\n                  : ListView.separated(\n                      itemCount: rows.length,\n                      separatorBuilder: (_, __) => const Divider(height: 1),\n                      itemBuilder: (BuildContext context, int index) {\n                        return _NearbyContactTile(row: rows[index]);\n                      },\n                    ),\n            ),\n          ],\n        ),\n      ),\n'''

new = '''      body: SafeArea(\n        child: CustomScrollView(\n          slivers: <Widget>[\n            if (_busy)\n              const SliverToBoxAdapter(\n                child: LinearProgressIndicator(minHeight: 2),\n              ),\n            SliverToBoxAdapter(\n              child: Padding(\n                padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),\n                child: _PrivateLocationCard(\n                  locationAccess: _locationAccess,\n                  location: _location,\n                  onUseLocation: _useMyLocationPrivately,\n                ),\n              ),\n            ),\n            if (!_contactAccess.canReadContacts)\n              SliverToBoxAdapter(\n                child: Padding(\n                  padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),\n                  child: _ContactPermissionCard(\n                    access: _contactAccess,\n                    onEnable: _enableContacts,\n                  ),\n                ),\n              ),\n            if (_message != null)\n              SliverToBoxAdapter(\n                child: Padding(\n                  padding: const EdgeInsets.symmetric(\n                    horizontal: 16,\n                    vertical: 4,\n                  ),\n                  child: MaterialBanner(\n                    content: Text(_message!),\n                    actions: <Widget>[\n                      TextButton(\n                        onPressed: () => setState(() => _message = null),\n                        child: const Text('Dismiss'),\n                      ),\n                    ],\n                  ),\n                ),\n              ),\n            SliverToBoxAdapter(\n              child: Padding(\n                padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),\n                child: SearchBar(\n                  hintText: 'Search contacts',\n                  leading: const Icon(Icons.search),\n                  onChanged: (String value) => setState(() => _query = value),\n                ),\n              ),\n            ),\n            SliverToBoxAdapter(\n              child: _NearbyControls(\n                distanceFilter: _distanceFilter,\n                sortOrder: _sortOrder,\n                onDistanceFilterChanged: (NearbyDistanceFilter value) {\n                  setState(() => _distanceFilter = value);\n                },\n                onSortChanged: (NearbySortOrder value) {\n                  setState(() => _sortOrder = value);\n                },\n              ),\n            ),\n            if (rows.isEmpty)\n              SliverFillRemaining(\n                hasScrollBody: false,\n                child: _EmptyNearbyResults(\n                  access: _contactAccess,\n                  hasContacts: _contacts.isNotEmpty,\n                  hasLocation: _location != null,\n                  hasActiveFilter:\n                      _distanceFilter != NearbyDistanceFilter.all ||\n                          _query.trim().isNotEmpty,\n                ),\n              )\n            else\n              SliverList(\n                delegate: SliverChildBuilderDelegate(\n                  (BuildContext context, int index) {\n                    if (index.isOdd) return const Divider(height: 1);\n                    return _NearbyContactTile(row: rows[index ~/ 2]);\n                  },\n                  childCount: rows.length * 2 - 1,\n                ),\n              ),\n            const SliverToBoxAdapter(child: SizedBox(height: 16)),\n          ],\n        ),\n      ),\n'''

if old not in text:
    if 'child: CustomScrollView(' in text:
        print('Phase 7 responsive layout already applied.')
        raise SystemExit(0)
    raise SystemExit('Expected Phase 7 fixed-header layout block not found.')

SCREEN.write_text(text.replace(old, new, 1))
print('Applied Phase 7 responsive CustomScrollView layout.')
